// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public { c = new Cooler(); }

    function testFuzz_property(address actor, address to_, uint256 loanID) public {
        vm.assume(actor != address(0));
        // Fresh C has no loans, so loans[loanID].lender == address(0) != actor.
        // Rule: a non-lender can never set approvals[loanID]; it must remain address(0)
        // (the call reverts in the reference, so state is unchanged).
        vm.prank(actor);
        bool ok;
        try c.approveTransfer(to_, loanID) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(c.approvals(loanID) == address(0), "non-lender must not set approvals");
    }
}
